#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int a[10][10];
    int r = -1, c = -1;
    long long rsum[10] = {0}, csum[10] = {0};
    long long d1 = 0, d2 = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
            rsum[i] += a[i][j];
            csum[j] += a[i][j];
            if (a[i][j] == 0) { r = i; c = j; }
            if (i == j) d1 += a[i][j];
            if (i + j == n - 1) d2 += a[i][j];
        }
    }

    long long S = 0;
    for (int i = 0; i < n; i++) {
        if (i != r && rsum[i] > 0) { S = rsum[i]; break; }
    }
    if (S == 0) S = d1 != 0 ? d1 : d2;

    long long val = S - rsum[r];

    printf("%lld\n%d\n%d\n", val, r + 1, c + 1);
    return 0;
}
